/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, I, Mul, NotImplementedError, Pow, Sym, SymFunction, cancel, exp, fn, mul, pi, pow, rational, residue, symbols, together } from '../../src';
import { sympyStr } from '../sympy-str';
import { equivalent } from '../sympy-equivalent';

describe("doctests of sympy.series.residues", () => {
  it("residue(1/x, x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(residue(pow(x, -1), x, rational(0)))).toBe('1');
  });
  it("residue(1/x**2, x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(residue(pow(x, -2), x, rational(0)))).toBe('0');
  });
  it("residue(2/sin(x), x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(residue(mul(2, pow(fn('sin', [x]), -1)), x, rational(0)))).toBe('2');
  });
});

